solution.solution.py:
class Recorder:
    def __init__(self, log, name):
        self.log = log
        self.name = name
        self.open = False

    def __enter__(self):
        self.open = True
        self.log.append(f"{self.name}: start")
        return self

    def note(self, text):
        if not self.open:
            raise RuntimeError("the recorder is closed")
        self.log.append(f"{self.name}: {text}")

    def __exit__(self, exc_type, exc_value, traceback):
        if exc_type is None:
            self.log.append(f"{self.name}: done")
        else:
            self.log.append(f"{self.name}: failed ({exc_type.__name__}: {exc_value})")
        self.open = False
        return False

unitTests:
@test("a normal run")
def _():
    log = []
    with Recorder(log, "import") as r:
        r.note("read 10 rows")
        r.note("skipped 2 rows")
    check_eq(log, ["import: start", "import: read 10 rows", "import: skipped 2 rows", "import: done"])

@test("a failing run")
def _():
    log = []
    def body():
        with Recorder(log, "sync") as r:
            r.note("connecting")
            raise ConnectionError("timed out")
    check_raises(ConnectionError, body)
    check_eq(log, ["sync: start", "sync: connecting", "sync: failed (ConnectionError: timed out)"])

@test("closed after the block")
def _():
    log = []
    with Recorder(log, "x") as r:
        pass
    check_raises(RuntimeError, r.note, "late")
    check_eq(log, ["x: start", "x: done"])

